// Build-time project data, with a committed snapshot as the safety net.
//
// WHY THIS EXISTS. work/[slug].astro used to throw on a network error, a
// non-200, or an empty result. That made davidedigerdesign.in a hard
// dependency of every deploy: a WordPress outage — or David's VPN, which does
// not route to that host — blocked releases of completely unrelated changes.
//
// Now WP is tried first and the snapshot catches everything else. The build
// never fails for want of WordPress; it warns loudly and carries on.
//
// The snapshot is COMMITTED and regenerated by `npm run snapshot`. It goes
// stale on its own, so the warning always prints its date.
//
// Plain .mjs, not .ts, so the Node snapshot script and the Astro build can
// import exactly the same fetch logic instead of keeping two copies in step.

// Static JSON import, NOT readFileSync. Vite bundles this module into
// dist/.prerender/chunks/ and does not copy the .json next to it, so a
// runtime file read resolved to a path that does not exist — and only on the
// fallback path, i.e. only during a real WP outage. A static import is
// inlined into the bundle at build time and cannot go missing.
import snapshot from './projects.snapshot.json' with { type: 'json' };

export const WP_API = 'https://davidedigerdesign.in/wp-json/wp/v2';

/** Per-request ceiling. The whole point is to fail fast to the snapshot. */
const TIMEOUT_MS = 10_000;

const isAttachmentId = (v) => typeof v === 'number' && Number.isFinite(v) && v > 0;

/**
 * Fetch projects + their resolved media from WordPress.
 * THROWS on any problem — the caller decides whether to fall back.
 * @returns {Promise<{projects: any[], media: [number, any][]}>}
 */
export async function fetchProjectsFromWp() {
  const endpoint = `${WP_API}/ded_project?_embed&per_page=100&orderby=menu_order&order=asc`;
  const res = await fetch(endpoint, { signal: AbortSignal.timeout(TIMEOUT_MS) });
  if (!res.ok) throw new Error(`WP REST returned ${res.status} ${res.statusText}`);

  const projects = await res.json();
  if (!Array.isArray(projects) || projects.length === 0) {
    throw new Error('WP returned no projects');
  }

  // Legacy ACF rows store bare attachment IDs rather than image objects.
  // Batch-resolve them so both consumers get full image data.
  const ids = new Set();
  for (const p of projects) {
    const a = p.acf ?? {};
    if (isAttachmentId(a.master_image)) ids.add(a.master_image);
    if (isAttachmentId(a.project_logo)) ids.add(a.project_logo);
    if (Array.isArray(a.gallery_items)) {
      for (const g of a.gallery_items) if (isAttachmentId(g?.g_image)) ids.add(g.g_image);
    }
  }

  const media = [];
  const all = Array.from(ids);
  for (let i = 0; i < all.length; i += 80) {
    const chunk = all.slice(i, i + 80);
    const url = `${WP_API}/media?include=${chunk.join(',')}&per_page=100&orderby=include`;
    const r = await fetch(url, { signal: AbortSignal.timeout(TIMEOUT_MS) });
    if (!r.ok) throw new Error(`Media batch failed (${r.status})`);
    for (const m of await r.json()) {
      media.push([m.id, {
        id: m.id,
        url: m.source_url,
        alt: m.alt_text ?? '',
        width: m.media_details?.width,
        height: m.media_details?.height,
        sizes: m.media_details?.sizes
          ? Object.fromEntries(
              Object.entries(m.media_details.sizes).map(([k, v]) => [k, v.source_url])
            )
          : undefined,
      }]);
    }
  }

  return { projects, media };
}

/** The committed snapshot, inlined at bundle time. */
export function readSnapshot() {
  return snapshot;
}

/**
 * Projects for the build. Tries WordPress, falls back to the snapshot on ANY
 * failure — network error, timeout, non-200, empty result, or a media batch
 * that will not resolve. Never throws.
 *
 * Deliberately all-or-nothing: a partial WP result is NOT merged with the
 * snapshot. Half-fresh, half-stale data would be far harder to reason about
 * than a build that is cleanly one or the other, and the banner would lie.
 *
 * @returns {Promise<{raw: any[], mediaMap: Map<number, any>, source: 'wp'|'snapshot', fetchedAt: string}>}
 */
export async function loadProjects() {
  try {
    const { projects, media } = await fetchProjectsFromWp();
    return {
      raw: projects,
      mediaMap: new Map(media),
      source: 'wp',
      fetchedAt: new Date().toISOString(),
    };
  } catch (e) {
    const snap = readSnapshot();
    const age = Math.round((Date.now() - Date.parse(snap.fetchedAt)) / 86_400_000);
    console.warn(
      `\n  ⚠ WP unreachable — built from snapshot dated ${snap.fetchedAt.slice(0, 10)} ` +
      `(${age} day${age === 1 ? '' : 's'} old, ${snap.projects.length} projects).\n` +
      `    Reason: ${(e instanceof Error ? e.message : String(e))}\n` +
      `    The build is fine. If WP is up and this still prints, check the VPN —\n` +
      `    IPVanish does not route to davidedigerdesign.in. Refresh with: npm run snapshot\n`
    );
    return {
      raw: snap.projects,
      mediaMap: new Map(snap.media),
      source: 'snapshot',
      fetchedAt: snap.fetchedAt,
    };
  }
}
